#ifndef PARAMS_DEFORMED_H
#define PARAMS_DEFORMED_H

// Match the existing InputMesh geometry generated by Mesh2D.
// BLFlatPlate uses Thickness/2 for both cap radii (currently (1/30)/2).
double sourceChord = 1.0;
double foilAngleDegrees = 15.0;
double sourceThickness = 1.0 / 30.0;
double leadingEdgeRadius = 0.5 * sourceThickness;  // 1/60
double trailingEdgeRadius = 0.5 * sourceThickness; // 1/60

// Used only by makeDeformed.sh / mesh --deformed.
// Root leading edge stays at (0,0,0). Tip offset is measured along local +u.
double rootChord = 1.5;
double tipChord = 0.5;
double tipLEOffset = 0.;

// The corrected rectangular source and trapezoid share these dimensions.
// TrapezoidWing preserves the thickness/radii of the actual input mesh;
// changing these values alone does not resize a stale InputMesh.
double targetThickness = 1.0 / 30.0;
double targetLeadingEdgeRadius = 0.5 * targetThickness;  // 1/60
double targetTrailingEdgeRadius = 0.5 * targetThickness; // 1/60

// Blend the fluid mesh to the unchanged far field in source (u,v) coordinates.
double taperNearNormal = 0.1;
double taperFarNormal = 5.0;
double taperNearUpstream = -1.0;
double taperFarUpstream = -5.0;
double taperNearDownstream = 2.0;
double taperFarDownstream = 6.0;

#endif
